#include "wm.h"
#include "config.h"

#include <stdio.h>
#include <string.h>

static Window popup;
static bool active;
static unsigned long unmap_serial;
static Monitor monitor;

bool switcher_is_active(void)
{
    return active;
}

bool switcher_blocks_enter(const XCrossingEvent *event)
{
    /* Ignore the crossing generated by hiding our own overlay, not a later
     * physical pointer crossing. Otherwise focus-follows-mouse undoes Alt+Tab. */
    return active || (unmap_serial != 0UL && event->serial == unmap_serial);
}

static bool alt_is_down(void)
{
    char keys[32];
    XModifierKeymap *mapping = XGetModifierMapping(wm.display);
    bool down = false;

    XQueryKeymap(wm.display, keys);
    if (mapping == NULL) return false;
    for (int modifier = 0; modifier < 8; ++modifier) {
        if ((AWM_ALT_MOD & (1U << (unsigned int)modifier)) == 0U) continue;
        for (int index = 0; index < mapping->max_keypermod; ++index) {
            unsigned int code = mapping->modifiermap[modifier * mapping->max_keypermod + index];
            if (code != 0U && ((unsigned char)keys[code / 8U] & (1U << (code % 8U))) != 0U)
                down = true;
        }
    }
    XFreeModifiermap(mapping);
    return down;
}

void switcher_cancel(void)
{
    if (!active) return;
    active = false;
    if (popup != None) {
        unmap_serial = NextRequest(wm.display);
        XUnmapWindow(wm.display, popup);
    }
    XUngrabKeyboard(wm.display, CurrentTime);
}

void switcher_cleanup(void)
{
    switcher_cancel();
    if (popup != None) XDestroyWindow(wm.display, popup);
    popup = None;
    unmap_serial = 0UL;
}

void switcher_raise(void)
{
    if (active && popup != None) XRaiseWindow(wm.display, popup);
}

static bool create_popup(void)
{
    XSetWindowAttributes attributes;
    XWMHints hints;

    if (popup != None) return true;
    memset(&attributes, 0, sizeof(attributes));
    attributes.override_redirect = True;
    attributes.background_pixel = wm.bar_background;
    attributes.event_mask = ExposureMask;
    popup = XCreateWindow(wm.display, wm.root, 0, 0, 1U, 1U, 0U,
                           CopyFromParent, InputOutput, CopyFromParent,
                           CWOverrideRedirect | CWBackPixel | CWEventMask, &attributes);
    if (popup == None) return false;
    XStoreName(wm.display, popup, "AntonioWM Alt-Tab");
    memset(&hints, 0, sizeof(hints));
    hints.flags = InputHint;
    hints.input = False;
    XSetWMHints(wm.display, popup, &hints);
    return true;
}

static void draw_icon(Client *client, int y, unsigned long background)
{
    unsigned int width = 24U, height = 24U;
    IconImage *icon = &client->taskbar_icon;

    if (!client->taskbar_icon_loaded) {
        (void)icon_load_client(client->window, 24U, icon);
        client->taskbar_icon_loaded = true;
    }
    if (icon->rgba != NULL) {
        if (icon->width > icon->height) height = 24U * icon->height / icon->width;
        else width = 24U * icon->width / icon->height;
        if (width == 0U) width = 1U;
        if (height == 0U) height = 1U;
    }
    if (!icon_draw(popup, icon, 12 + (24 - (int)width) / 2,
                   y + (32 - (int)height) / 2, width, height, background)) {
        draw_rectangle(popup, wm.bar_foreground, 14, y + 7, 19U, 17U);
        draw_line(popup, wm.bar_foreground, 14, y + 12, 33, y + 12);
    }
}

void switcher_refresh(void)
{
    size_t count = 0U, selected = 0U, index = 0U, first, rows;
    int width, height, available;
    char heading[96];
    Client *client;

    if (!active) return;
    for (client = wm.clients; client != NULL; client = client->next) {
        if (!client_is_cycle_candidate(client)) continue;
        if (client == wm.focused) selected = count;
        ++count;
    }
    if (count == 0U || monitor.width < 96 || monitor.height < 72) {
        switcher_cancel();
        return;
    }
    if (!create_popup()) {
        switcher_cancel();
        return;
    }
    width = monitor.width - 32;
    if (width > 600) width = 600;
    available = (monitor.height - 48) / 32;
    if (available < 1) available = 1;
    rows = count < (size_t)available ? count : (size_t)available;
    height = 32 + (int)rows * 32;
    first = selected >= rows ? selected - rows + 1U : 0U;
    XMoveResizeWindow(wm.display, popup,
                       monitor.x + (monitor.width - width) / 2,
                       monitor.y + (monitor.height - height) / 2,
                       (unsigned int)width, (unsigned int)height);
    draw_fill(popup, wm.bar_background, 0, 0, (unsigned int)width, (unsigned int)height);
    (void)snprintf(heading, sizeof(heading), "Alt+Tab   %zu / %zu", selected + 1U, count);
    draw_text_ellipsized(popup, wm.bar_foreground, 12, draw_text_baseline(32),
                         12, 0, (unsigned int)(width - 24), 32U, heading);
    for (client = wm.clients; client != NULL; client = client->next) {
        int y;
        unsigned long background;
        if (!client_is_cycle_candidate(client)) continue;
        if (index < first || index >= first + rows) { ++index; continue; }
        y = 32 + (int)(index - first) * 32;
        background = index == selected ? wm.bar_selected : wm.bar_item;
        draw_fill(popup, background, 4, y, (unsigned int)(width - 8), 32U);
        draw_icon(client, y, background);
        draw_text_ellipsized(popup, wm.bar_foreground, 48,
                             y + draw_text_baseline(32), 48, y,
                             (unsigned int)(width - 60), 32U,
                             client->title != NULL ? client->title : "(sin titulo)");
        ++index;
    }
    draw_rectangle(popup, wm.bar_separator, 0, 0,
                    (unsigned int)(width - 1), (unsigned int)(height - 1));
    XMapRaised(wm.display, popup);
}

void switcher_step(int direction)
{
    if (!active) {
        Window root_return, child;
        int x, y, child_x, child_y;
        unsigned int mask;
        menu_close();
        task_preview_cancel();
        client_sync_focus();
        if (wm.focused != NULL) monitor_for_client(wm.focused, &monitor);
        else if (XQueryPointer(wm.display, wm.root, &root_return, &child,
                                &x, &y, &child_x, &child_y, &mask))
            monitor_for_rectangle(x, y, 1, 1, &monitor);
        else monitor_primary(&monitor);
        /* Promote the passive Tab grab: releases must still arrive after Tab up. */
        if (XGrabKeyboard(wm.display, wm.root, False, GrabModeAsync,
                           GrabModeAsync, wm.last_event_time) != GrabSuccess) {
            client_cycle_focus(direction);
            return;
        }
        active = true;
    }
    client_cycle_focus(direction);
    switcher_refresh();
    /* A fast chord may already have released Alt before its press was processed. */
    if (!alt_is_down()) switcher_cancel();
}

bool switcher_handle_event(XEvent *event)
{
    if (!active) return false;
    if (event->type == Expose && event->xexpose.window == popup) {
        switcher_refresh();
        return true;
    }
    /* Pointer motion must not schedule a task preview over the switcher. */
    if (event->type == MotionNotify) return true;
    if (event->type == KeyRelease) {
        wm.last_event_time = event->xkey.time;
        if (!alt_is_down()) switcher_cancel();
        return true;
    }
    if (event->type == KeyPress) {
        KeySym symbol = XLookupKeysym(&event->xkey, 0);
        unsigned int modifiers = keyboard_clean_modifiers(event->xkey.state);
        if ((symbol == AWM_CYCLE_KEY || symbol == XK_ISO_Left_Tab) &&
            (modifiers == AWM_ALT_MOD || modifiers == (AWM_ALT_MOD | ShiftMask))) {
            wm.last_event_time = event->xkey.time;
            switcher_step((modifiers & ShiftMask) != 0U ? -1 : 1);
            return true;
        }
        if (symbol == XK_Alt_L || symbol == XK_Alt_R ||
            symbol == XK_Shift_L || symbol == XK_Shift_R) return true;
        switcher_cancel();
        return symbol == XK_Escape;
    }
    if (event->type == ButtonPress ||
        (event->type == DestroyNotify && client_find(event->xdestroywindow.window) != NULL) ||
        (event->type == UnmapNotify && client_find(event->xunmap.window) != NULL))
        switcher_cancel();
    return false;
}
